// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _run(uint256 r) internal {
        vm.assume(msg.sender == c.owner());
        try c.setRewardRate(r) {} catch { return; }
        assertTrue(r == c.rewardRate());
    }

    function testFuzz_run(uint256 r) public {
        _run(r);
    }

    receive() external payable {}
}
